From 7dedf1bee6a22b249f6a9932449979269232f0cb Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 18:08:42 +0100
Subject: [PATCH] plasmoid: add a switch to rotate the screen automatically

Turning automatic rotation on or off meant going to System Settings each
time, even though it is often only wanted for a moment. The applet now
shows a switch for it when a screen supports automatic rotation.

BUG: 503732
---
 plasmoid/kscreenapplet.cpp | 61 ++++++++++++++++++++++++++++++++++++++
 plasmoid/kscreenapplet.h   | 15 ++++++++++
 plasmoid/main.qml          | 12 ++++++++
 3 files changed, 88 insertions(+)

diff --git a/plasmoid/kscreenapplet.cpp b/plasmoid/kscreenapplet.cpp
index b48b785d..3b3992c6 100644
--- a/plasmoid/kscreenapplet.cpp
+++ b/plasmoid/kscreenapplet.cpp
@@ -48,6 +48,42 @@ int KScreenApplet::connectedOutputCount() const
     return m_connectedOutputCount;
 }

+bool KScreenApplet::autoRotateAvailable() const
+{
+    return m_autoRotateAvailable;
+}
+
+bool KScreenApplet::autoRotate() const
+{
+    return m_autoRotate;
+}
+
+void KScreenApplet::setAutoRotate(bool autoRotate)
+{
+    if (!m_screenConfiguration || autoRotate == m_autoRotate) {
+        return;
+    }
+
+    auto policy = KScreen::Output::AutoRotatePolicy::Never;
+    if (autoRotate) {
+        // In tablet mode, keep the default of rotating only while in tablet mode
+        policy = m_screenConfiguration->tabletModeEngaged() ? KScreen::Output::AutoRotatePolicy::InTabletMode : KScreen::Output::AutoRotatePolicy::Always;
+    }
+
+    const KScreen::ConfigPtr config = m_screenConfiguration->clone();
+    const auto outputs = config->connectedOutputs();
+    for (const KScreen::OutputPtr &output : outputs) {
+        if (output->capabilities() & KScreen::Output::Capability::AutoRotation) {
+            output->setAutoRotatePolicy(policy);
+        }
+    }
+
+    new KScreen::SetConfigOperation(config);
+
+    m_autoRotate = autoRotate;
+    Q_EMIT autoRotateChanged();
+}
+
 void KScreenApplet::applyLayoutPreset(KScreen::OsdAction::Action action)
 {
     KScreen::OsdAction::applyAction(m_screenConfiguration, action);
@@ -69,6 +105,31 @@ void KScreenApplet::checkOutputs()
     if (m_connectedOutputCount != oldConnectedOutputCount) {
         emit connectedOutputCountChanged();
     }
+
+    const bool oldAutoRotateAvailable = m_autoRotateAvailable;
+    const bool oldAutoRotate = m_autoRotate;
+    m_autoRotateAvailable = false;
+    m_autoRotate = false;
+    for (const KScreen::OutputPtr &output : outputs) {
+        if (!output->isConnected() || !(output->capabilities() & KScreen::Output::Capability::AutoRotation)) {
+            continue;
+        }
+        m_autoRotateAvailable = true;
+        switch (output->autoRotatePolicy()) {
+        case KScreen::Output::AutoRotatePolicy::Never:
+            break;
+        case KScreen::Output::AutoRotatePolicy::InTabletMode:
+            m_autoRotate |= m_screenConfiguration->tabletModeEngaged();
+            break;
+        case KScreen::Output::AutoRotatePolicy::Always:
+            m_autoRotate = true;
+            break;
+        }
+    }
+
+    if (m_autoRotateAvailable != oldAutoRotateAvailable || m_autoRotate != oldAutoRotate) {
+        Q_EMIT autoRotateChanged();
+    }
 }

 QVariant KScreenApplet::availableActions()
diff --git a/plasmoid/kscreenapplet.h b/plasmoid/kscreenapplet.h
index fc5b2a0e..1f527396 100644
--- a/plasmoid/kscreenapplet.h
+++ b/plasmoid/kscreenapplet.h
@@ -31,6 +31,14 @@ class KScreenApplet : public Plasma::Applet
      */
     Q_PROPERTY(int connectedOutputCount READ connectedOutputCount NOTIFY connectedOutputCountChanged FINAL)
     Q_PROPERTY(QVariant availableActions READ availableActions CONSTANT STORED false FINAL)
+    /**
+     * Whether any connected output can rotate automatically
+     */
+    Q_PROPERTY(bool autoRotateAvailable READ autoRotateAvailable NOTIFY autoRotateChanged FINAL)
+    /**
+     * Whether automatic rotation is currently in effect
+     */
+    Q_PROPERTY(bool autoRotate READ autoRotate WRITE setAutoRotate NOTIFY autoRotateChanged FINAL)

 public:
     explicit KScreenApplet(QObject *parent, const KPluginMetaData &data, const QVariantList &args);
@@ -40,16 +48,23 @@ public:

     int connectedOutputCount() const;

+    bool autoRotateAvailable() const;
+    bool autoRotate() const;
+    void setAutoRotate(bool autoRotate);
+
     Q_INVOKABLE void applyLayoutPreset(KScreen::OsdAction::Action action);

     static QVariant availableActions();

 Q_SIGNALS:
     void connectedOutputCountChanged();
+    void autoRotateChanged();

 private:
     void checkOutputs();

     KScreen::ConfigPtr m_screenConfiguration;
     int m_connectedOutputCount = 0;
+    bool m_autoRotateAvailable = false;
+    bool m_autoRotate = false;
 };
diff --git a/plasmoid/main.qml b/plasmoid/main.qml
index 326027db..88aae245 100644
--- a/plasmoid/main.qml
+++ b/plasmoid/main.qml
@@ -13,6 +13,7 @@ import QtQuick.Layouts
 import org.kde.config as KConfig
 import org.kde.kcmutils as KCMUtils
 import org.kde.kirigami as Kirigami
+import org.kde.plasma.components as PlasmaComponents3
 import org.kde.plasma.core as PlasmaCore
 import org.kde.plasma.plasma5support as P5Support
 import org.kde.plasma.plasmoid
@@ -84,6 +85,17 @@ PlasmoidItem {
             screenLayouts: Plasmoid.availableActions // qmllint disable missing-property
         }

+        PlasmaComponents3.Switch {
+            Layout.fillWidth: true
+            Layout.topMargin: Kirigami.Units.smallSpacing * 2
+            Layout.leftMargin: Kirigami.Units.smallSpacing
+            Layout.rightMargin: Kirigami.Units.smallSpacing
+            visible: Plasmoid.autoRotateAvailable // qmllint disable missing-property
+            text: i18n("Rotate Screen Automatically")
+            checked: Plasmoid.autoRotate // qmllint disable missing-property
+            onToggled: Plasmoid.autoRotate = checked // qmllint disable missing-property
+        }
+
         PresentationModeItem {
             Layout.fillWidth: true
             Layout.topMargin: Kirigami.Units.smallSpacing * 2
-- 
